      llsf_NI.phase = (frames >> llsf_p.phaseShift) & llsf_p.phaseMask;
      llsf_NI.n = (frames >> llsf_p.nShift) & llsf_p.nMask;
      llsf_NI.frame = (frames  & llsf_p.framesMask) & frames;
